    val records = listOf(
        Record(FeoriaTranslationCatalog.Entry("cross-tone6-friday:983e417ab1c91a6a2d72",
            "Стра́стию Твое́ю честно́ю почти́л еси́ обезче́стенное естество́ челове́ческое: те́мже чту́ще Тя́ со стра́хом, велича́ем держа́ву Твою́, и ве́рно сла́вим: сла́вно бо просла́вися.",
            "Своими святыми страданиями Ты почтил обесчещенную человеческую природу. Поэтому, почитая Тебя со страхом, мы прославляем Твое могущество и с верой воспеваем: ибо славно Он прославился.", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "cross-tone6-friday", 1, 1, "50af8984918e072ca84798188e7f72068b1d75f5ceb4eaae42dd6b7532801771", "983e417ab1c91a6a2d72610510e02943f6077c807500f0634ffa87ae522db25e", "e65dcab3a3fc5236ec48aa5226059970347aa89e40e546599976c1816aacaff0"),
        Record(FeoriaTranslationCatalog.Entry("cross-tone6-friday:3a959ae60cab296658bc",
            "Кро́вию Твое́ю, Сло́ве, крове́й непра́ведное проли́тие уста́вил еси́, и очи́стил еси́ от скве́рны зло́бныя естество́ челове́ческое, Всеси́льне. Те́м сла́вим спаса́емии держа́ву Твою́.",
            "Своей Кровью Ты, Слово, остановил неправедное пролитие крови и очистил человеческую природу от злой скверны, Всемогущий. Поэтому мы, спасаемые Тобой, славим Твое могущество.", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "cross-tone6-friday", 1, 2, "c25a4ae3ea66f6c98c630a95710a8a2a3d96b13655806626e84ed63dabbb0641", "3a959ae60cab296658bcebfdd017a7d4bbc5fc5fba86cbd5f7f78882b1cd0fd4", "37b05f673a5551612cba1e455ef4e56443466713c839fcb4b29d7d462defb72b"),
        Record(FeoriaTranslationCatalog.Entry("cross-tone6-friday:b19bcadf7bd08ea82e14",
            "Мученичен: Зве́ря кровопи́йцу победи́ вои́стинну, достохва́льное му́ченик сопротивостоя́ние: о́гненное покори́ естество́ росо́ю Боже́ственныя благода́ти, и зе́льну бу́рю многобо́жия уста́ви.",
            "Мученичен: Достойное похвалы сопротивление мучеников поистине победило кровожадного зверя, росой Божественной благодати покорило огненную стихию и уняло сильную бурю многобожия.", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "cross-tone6-friday", 1, 3, "f6f938d176bdadaf8e5a50c5d5071e4c1cf8720de6901ae4607a7c5656a2ea1e", "b19bcadf7bd08ea82e1482bb3b59025897f1c7e621618b3ae0a84efb25ac8c3c", "39949f69a1d9c077dd5d53089e938f5ab76a6ea3daa5bcf3783afeede2265e5b"),
        Record(FeoriaTranslationCatalog.Entry("cross-tone6-friday:6f8c26a00199d41693a8",
            "Мученичен: Ту́чами крове́й одожде́ния пре́лести изсуши́вше, ту́чи исцеле́ний то́чите ми́рови, и пла́мень страсте́й отгоня́ете безбо́жия. Те́мже, му́ченицы, блажи́ми есте́.",
            "Мученичен: Ливнями своей крови высушив ливни заблуждения, вы изливаете миру ливни исцелений и отгоняете пламя безбожных страстей. Поэтому, мученики, вас прославляют.", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "cross-tone6-friday", 1, 4, "1baa7904d98e4643e03695924ec4af0addff53cb29b30994abf4bb9a8dcf9d15", "6f8c26a00199d41693a8e546c67614ae2e263bf07b984492ecd21ad71f687a8a", "961e5075150ed6e09af7d8554ecbb049f5606a3313b2d8e017d11b7b7c4d8007"),
        Record(FeoriaTranslationCatalog.Entry("cross-tone6-friday:c794d31766139781e4d1",
            "Богородичен: Добро́ты, ни ви́да иму́ща внегда́ страда́ти, кра́снаго добро́тою, неискусобра́чная Отрокови́це, смотря́ющи Тя́ ве́рных удобре́ние, ма́терски восклица́ше, и любо́вию Тя́ сла́вляше.",
            "Богородичен: Видя, что Ты, прекрасный красотой, во время страдания лишен красоты и вида, Дева, не познавшая брака, украшение верных, по-матерински восклицала и с любовью славила Тебя.", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "cross-tone6-friday", 1, 5, "00d44319b916e9d788b4f0e6c648961c89075b1be6083774325832859014e108", "c794d31766139781e4d1db2fc67bad99d1f8d3b6c343384321cd0e35a0affcfd", "b0222b0896b9801ba53062aeb0289445faefdd3ab98936e9be822a4863db5542"),
        Record(FeoriaTranslationCatalog.Entry("apostles-stachys-amplias-urban-narcissus-apelles-aristobulus-tone1:48b267c855ff81717187",
            "Верою почитающия вашу, священнии благоглаголивии, память/ и торжествующия радостно,/ страсте́й мглы изба́вите и вечныя радости причастники соделайте.",
            "Священные проповедники, избавьте от мрака страстей тех, кто с верой почитает вашу память и радостно празднует ее, и сделайте их причастниками вечной радости.", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "apostles-stachys-amplias-urban-narcissus-apelles-aristobulus-tone1", 1, 1, "157c45586b199e97c757ac668944cd151d58f8da907ce338f329092c011f0d84", "48b267c855ff8171718798a9714da1dfdb49f12aba4b1878a7adf5d5446c4011", "163bb5a85f37a009219cf2b489027a8c62bd84e2b567940789e67fa740ccc7f5"),
        Record(FeoriaTranslationCatalog.Entry("apostles-stachys-amplias-urban-narcissus-apelles-aristobulus-tone1:13e22d6935d1634e2206",
            "Стопа́м последующе Христа, воплоще́ннаго за милосердие, пребогатии,/ Сего же повелением Богоначальным служа́ще,/ яви́стеся всех заблуждших наставницы к благочестию.",
            "Следуя по стопам Христа, воплотившегося по милосердию, и служа по Его Божественному повелению, вы, богатейшие, стали наставниками в благочестии для всех заблудших.", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "apostles-stachys-amplias-urban-narcissus-apelles-aristobulus-tone1", 1, 2, "d2330311d8f6c96615e2a1442ee362442173a5b73338757990e2899bc6f3f0b7", "13e22d6935d1634e2206460602a8336bc3b4a3ccbb5878c4e4cf1421aafc968d", "9372fc2f2018727ec8ed0db0721f5af0c26f49d46eef11c2cf259f32795e3d81"),
        Record(FeoriaTranslationCatalog.Entry("apostles-stachys-amplias-urban-narcissus-apelles-aristobulus-tone1:fb22750c3f73d5946359",
            "Стахи́я и Ампли́я мудраго, и Урва́на, Апе́ллия же, и Нарки́сса, и Аристову́ла,/ Христовы ученики бывшия,/ верою сошедшеся, до́лжно ублажи́м.",
            "Сойдясь с верой, как подобает, прославим Стахия, мудрого Амплия, Урвана, Апеллия, Наркисса и Аристовула, ставших учениками Христа.", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "apostles-stachys-amplias-urban-narcissus-apelles-aristobulus-tone1", 1, 3, "c36545bb4d8b5f52fdc30bea0a031f234b14fbf8d4fdade463777f7de1d96d08", "fb22750c3f73d5946359dd66e5719f4ab01bb26e8af434e5e6a1c96174414e5c", "b0e8f43f4d00e95e7693bf3f475b628fa73bbcfce024dae62ad2f7b27a21e2a0"),
        Record(FeoriaTranslationCatalog.Entry("apostles-stachys-amplias-urban-narcissus-apelles-aristobulus-tone1:283f2ca46ef270bd8e46",
            "Богородичен: Явственную го́ру Божию, киво́т святый и трапе́зу,/ ста́мну же всезлатую, чистую Иисусову палату,/ Благословенную в жена́х ублажи́м.",
            "Богородичен: Прославим Благословенную среди женщин, явленную гору Божию, святой ковчег и трапезу, золотой сосуд и чистый дворец Иисуса.", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "apostles-stachys-amplias-urban-narcissus-apelles-aristobulus-tone1", 1, 4, "f4dc2432af0f11f1cd859239094fc8565c5d15e80956e1549289588356d107ff", "283f2ca46ef270bd8e469d26f28abb97154d7ea1ed9e235e24542e43fb931263", "246a15b1a0c0068df3b99ba0ffd751d8a51f3163e6643baa2d28828acb49afb4"),
        Record(FeoriaTranslationCatalog.Entry("martyr-epimachus-tone4:7356fa43cfd588f99b70",
            "Воспою Тебе́, Го́споди Боже мой,/ я́ко показа́л еси́ нам па́мять мученика, озаря́ющу всяческая,/ я́ко един Многомилостив.",
            "Воспою Тебе, Господи, Боже мой, ибо Ты явил нам память мученика, озаряющую все, как единственный Многомилостивый.", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "martyr-epimachus-tone4", 1, 1, "9cd8369f33cf5d8ef90758cee20c90d8f058a2b45800cd5787c53b837c6a34f9", "7356fa43cfd588f99b70d6397b0027e091faa3d05ae3913034739acbf8907812", "a51c8638d56e00b3d940c749cf76769d654b73d2426e825b54715665e242cc1b"),
        Record(FeoriaTranslationCatalog.Entry("martyr-epimachus-tone4:8faffd9a068aea0682f5",
            "Воспою Тебе́, Го́споди Боже мой,/ я́ко непобеди́ма Твоего́ показа́л еси́ мученика,/ поборника в мученицех на безбожие.",
            "Воспою Тебе, Господи, Боже мой, ибо Ты явил Своего непобедимого мученика, борца среди мучеников против безбожия.", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "martyr-epimachus-tone4", 1, 2, "d528f003298e98bd0675a615809bf715dc0d4b26b11c7d49f04a51a116fa999e", "8faffd9a068aea0682f5e4dc86a0ffbf650b755a68dd7644ed933f1773fbd962", "6731822538d9fad08d9ad783e645de81c98781e3944711750fe08cc39d7640e7"),
        Record(FeoriaTranslationCatalog.Entry("martyr-epimachus-tone4:75739a4ab8b5e0a0f0ee",
            "Воспою Тебе́, Го́споди Боже мой,/ я́ко дарова́нии Божественными Твоего́ страдальца украси́л еси́, Епима́ха,/ и честию венчал еси́.",
            "Воспою Тебе, Господи, Боже мой, ибо Ты украсил Божественными дарами Своего страдальца Епимаха и увенчал его честью.", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "martyr-epimachus-tone4", 1, 3, "50e54bf845fdbff4133f9e5a80b020ac5f78c04644afc52f10111373f4f0c8e8", "75739a4ab8b5e0a0f0ee28b1eeeebddcad5b19ce51c0a80451ab77d884e49150", "67ddd4e1cd051966cbe7196de4780b39ba0985c801ade589c4d705e0ad9424e1"),
        Record(FeoriaTranslationCatalog.Entry("martyr-epimachus-tone4:3db86fe711d360c246fc",
            "Богородичен: Воспою Тебе́, Го́споди Боже мой,/ я́ко безсе́менно из утро́бы Девы родился еси́,/ Ея́же ради и спасаеши вся, я́ко един Многомилостив.",
            "Богородичен: Воспою Тебе, Господи, Боже мой, ибо Ты без семени родился из чрева Девы, ради Которой и спасаешь всех, как единственный Многомилостивый.", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "martyr-epimachus-tone4", 1, 4, "778d6f0e714b0be7fa955c068bf46a2a7930f9a2978feefaedba4066d69fa19d", "3db86fe711d360c246fcc9eb7c16f6cec4da650663aecaf6bd026b1b41d1e363", "6af5f4dc6db11338d9cee981abc3e389f3ccc079046c3497b1a8ecbe66c2892b"),
        Record(FeoriaTranslationCatalog.Entry("cross-tone6-friday:682d180d3ef4f7b67740",
            "Тебе́ на вода́х пове́сившаго всю́ зе́млю неодержи́мо на Дре́во вознесе́на, и в ре́бра пробода́ема, смотря́ющее Со́лнце помрача́шеся, все́х просвеще́ние разуме́ющее Тя́, Го́споди.",
            "Видя Тебя, повесившего всю землю на водах без опоры, вознесенным на Древо и пронзаемым в бок, солнце помрачалось, узнавая в Тебе, Господи, просвещение всех.", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "cross-tone6-friday", 3, 1, "dbb6c90c4c2b97e6e735035c0724f3815b97a99e1c7abdb1f792986a8d1886f1", "682d180d3ef4f7b67740187a08b28a73f9178115f69d819d45ad4b0becccfa7f", "85330893f43860de091e7e97cb1b6313267fcad98e6520db6a0a823cecdb36f6"),
        Record(FeoriaTranslationCatalog.Entry("cross-tone6-friday:9545f106fb48db0eebfe",
            "Уязвля́ется Твои́ми гвоздьми́, Долготерпели́ве, и́же в раи́ дре́вле уязви́вый Ада́ма злоде́й, и уязви́вся, неисце́льный во ве́ки пребы́сть: ве́рнии же обрето́хом все́х я́зв исцеле́ние.",
            "Твоими гвоздями, Долготерпеливый, ранен злодей, некогда ранивший Адама в раю, и, раненный, навсегда остался неисцелимым; мы же, верные, обрели исцеление всех ран.", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "cross-tone6-friday", 3, 2, "a42ce0d99303132cb03d9756b2b1a1a65fcea806c86a7255aa407e15356dbea4", "9545f106fb48db0eebfe6441e3a07760f290d78c3f912a063979afd0c6b64f35", "b341970ea6b1ae29e139a668b3d269a9c4ceb3dd67b2790e293834f6a79b5941"),
        Record(FeoriaTranslationCatalog.Entry("cross-tone6-friday:1556d156a43d8056ab79",
            "Мученичен: Егда́ ли́к а́нгельский, зря́ше му́чеников стада́ за А́гнца поже́ршагося сдробля́ема, дивля́шеся: ка́ко веще́ственнии невеще́ственныя враги́ побежда́ху, побе́ды венцы́ прие́млюще?",
            "Мученичен: Когда ангельский сонм видел стада мучеников, раздробляемых за закланного Агнца, он удивлялся: как облеченные плотью побеждали бесплотных врагов, принимая победные венцы?", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "cross-tone6-friday", 3, 3, "8be19076349a56d482b631cb472236bc08ebbee17f22446e0c6a4373114e2037", "1556d156a43d8056ab795d49899eb87bc40cf03e7e676eba07ce60bf73dbfea8", "327bceafa74b6bd89bb8ac883690405a3f5224c1c551149bd951263a7cf38585"),
        Record(FeoriaTranslationCatalog.Entry("cross-tone6-friday:95188412f7b0187618c9",
            "Мученичен: Си́лою одева́еми святи́и, в кре́пости еди́наго вся́ могу́щаго, со враго́м сплета́хуся, и того́ некре́пкую попира́ху си́лу, венцы́ от Бо́га прие́млюще.",
            "Мученичен: Облекаясь силой Единственного, Кто может все, святые крепко вступали в борьбу с врагом и попирали его бессильную мощь, принимая венцы от Бога.", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "cross-tone6-friday", 3, 4, "b15ad58f276ed9e84beb73f26a11bba9c1d2376a7c275060fb889932e57f3807", "95188412f7b0187618c9bb8f530b39e0f1a83b4a06ebd16acc8264b45fc34ad5", "c00a906ec5a5054e06e33665ac7626618d8628d107977c7eeec4e4c8b3ee0296"),
        Record(FeoriaTranslationCatalog.Entry("cross-tone6-friday:131e09b74c6016d1bd74",
            "Богородичен: Ты́ из Тебе́ ро́ждшагося, я́ко ви́дела еси́ уя́звлена копие́м, уязви́лася еси́ се́рдцем, Пречи́стая Всенепоро́чная, и дивя́щися глаго́лала еси́: что́ Ти воздаде́, Ча́до, собо́р пребеззако́нный?",
            "Богородичен: Увидев Рожденного от Тебя раненным копьем, Ты была ранена в сердце, Пречистая, совершенно Непорочная, и с изумлением говорила: \"Чем отплатило Тебе, Дитя, это беззаконнейшее сборище?\"", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "cross-tone6-friday", 3, 5, "0f3667d1a19b625d035948b221892864cb8563881e5c2d4d401aad5b57fa5d73", "131e09b74c6016d1bd7448e650800566c7f32a5a6414fffe349d3c5adda900be", "9f7695d76c4a10046cf5ebd798fc7e908e27cf291846bd880c4712ccc5e65e55"),
        Record(FeoriaTranslationCatalog.Entry("apostles-stachys-amplias-urban-narcissus-apelles-aristobulus-tone1:bbddde405696d4bdd5bc",
            "Я́ко клас многоплоден, мудре, яви́лся еси́,/ словом зна́ния, гладом та́ющия веры пита́я, Стахи́е Богоблаженне,/ и пи́щи лучшия причастники благода́тию соде́лав/ силою Духа.",
            "Ты явился многоплодным колосом, мудрый, Богом ублаженный Стахий: словом знания питая изнемогающих от голода веры, благодатью, силой Духа, ты сделал их причастниками лучшей пищи.", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "apostles-stachys-amplias-urban-narcissus-apelles-aristobulus-tone1", 3, 1, "2f719294462114e2f52c0916d357ddd3c1eb0ee3c331f1a5f9d5b4768375bd5f", "bbddde405696d4bdd5bc499bc49aa5f417ca140d73e909b7b6f8392e2f6e3622", "1b1db5916e2d2b6a27bbaae36fa20b8e9e874602f87acf95c78f1aa65fb1e20f"),
        Record(FeoriaTranslationCatalog.Entry("apostles-stachys-amplias-urban-narcissus-apelles-aristobulus-tone1:f97a5effb0688daaa612",
            "Мре́жею язы́ка, благоестественно взем, уловил еси́ из глубины́ лести, апостоле,/ и принесл еси́ Боже́ственно пищу пришедшему, Нарки́ссе,/ спасти́ заблуждшаго, Царю́ и Влады́це тва́ри.",
            "Искусно закинув сеть своего языка, ты, апостол Наркисс, извлек из глубины заблуждения священную пищу и принес ее Царю и Владыке творения, пришедшему спасти заблудшего.", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "apostles-stachys-amplias-urban-narcissus-apelles-aristobulus-tone1", 3, 2, "23e20f81d1c30bc11fb593c688909244220a444328f7a91981b3b39f3316ee0d", "f97a5effb0688daaa61233707de87fe3ef574b6a1cf3c74a824e070fdf8bc1d9", "3716ce3e4b1d4f60406047b83c7af63e0140154d63368502b700d7369444425e"),
        Record(FeoriaTranslationCatalog.Entry("apostles-stachys-amplias-urban-narcissus-apelles-aristobulus-tone1:f2e3a00e93f83e10ed5c",
            "Потекл еси́, я́коже звезда от востока, устреми́вся и Вретани́йския гра́ды постигл еси́,/ Христово проповедуя Ева́нгелие и просвещая благода́тию, блаже́нне Аристову́ле,/ верно приемлющия слово твое́.",
            "Устремившись с востока, словно звезда, ты достиг городов Британии, блаженный Аристовул, проповедуя Евангелие Христа и благодатью просвещая тех, кто с верой принимает твое слово.", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "apostles-stachys-amplias-urban-narcissus-apelles-aristobulus-tone1", 3, 3, "ed1bd53558233575452749d45144f921991e438a3057bf09704a9f57a02f6858", "f2e3a00e93f83e10ed5cd051cbfec1050510bd578ab29599bb44b08a124224e9", "fa4baf20f6005393a7a84b93e884796aaf41fbbeb503482957e41dc9f6ce5d3d"),
        Record(FeoriaTranslationCatalog.Entry("apostles-stachys-amplias-urban-narcissus-apelles-aristobulus-tone1:afd506d3417d69e084ee",
            "Богородичен: Черто́г светоносен Христов и престол высочайший, Богородительнице,/ яви́лася еси́, Всенепоро́чная:/ в Тебе́ бо Един почи́в, на́ша отъят труды́/ и будущую достойным угото́ва осла́бу.",
            "Богородичен: Ты явилась светоносным чертогом Христа и высочайшим престолом, Богородительница, совершенно Непорочная: ибо Единый, почив в Тебе, избавил нас от трудов и приготовил достойным будущий покой.", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "apostles-stachys-amplias-urban-narcissus-apelles-aristobulus-tone1", 3, 4, "d42fb385a46855ee35d30e6c3e675da767cd47b55be6fbd4780a4b80f1182b65", "afd506d3417d69e084ee6cd8b7a10e4d5bfb31956e0068a6072bd2d58676875c", "b20f558da9c3a41c040a93593f98507ba570283f59db46e8a7fbfd7e0e5a6f75"),
        Record(FeoriaTranslationCatalog.Entry("martyr-epimachus-tone4:5fad8ef267d545e1d62f",
            "Суровство́ нечестивых омрачи́л есть,/ всехвальным Крестом хваля́ся,/ непобедимый венценосец Христов, мученик Епима́х.",
            "Непобедимый венценосец Христа, мученик Епимах, помрачил свирепость нечестивых, хвалясь Крестом, достойным всякой хвалы.", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "martyr-epimachus-tone4", 3, 1, "e3f4713aec50018c30c0b48f79ad84c89b388813a3e022dbf507a7d8b38f09c9", "5fad8ef267d545e1d62f1c7fb2a8941bea554969eacd9734f8fd7aea3ba28562", "87c09ac9472b971f14a4ce8af07b6aee475d55d0331782088457192873142a4c"),
        Record(FeoriaTranslationCatalog.Entry("martyr-epimachus-tone4:7ef8af8aeb391a28d167",
            "Славу презре́в привре́менную и к подвиго́м совлекся,/ радовашеся Богомудрый и наследник Христов,/ мученик Епима́х.",
            "Презрев временную славу и обнажившись для подвигов, радовался мудрый в Боге наследник Христа, мученик Епимах.", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "martyr-epimachus-tone4", 3, 2, "19b39aefaa2c0e8328a771d28d85357685fd8911b873f350e807bf3f8b4b4545", "7ef8af8aeb391a28d1675177ad1a619fdee87c9de6409c99b887f4448bff64f8", "ea0fe6da1fde0885671b463d6ae0b545b21272ac52a461e169f6b629326ec3ef"),
        Record(FeoriaTranslationCatalog.Entry("martyr-epimachus-tone4:33e762c7ef856074595e",
            "Богородичен: Ра́дуйся, Ма́ти Приснодево,/ Бо́га Слова во чреве Твое́м вместившая и рождшая воплощеннаго/ я́ко Бо́га ку́пно и Человека.",
            "Богородичен: Радуйся, Матерь, всегда Дева, вместившая в Своем чреве Бога Слово и родившая Его воплотившимся, одновременно Богом и Человеком.", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "martyr-epimachus-tone4", 3, 3, "42fbe44ca6f9082d284e62616f9ff6e745cd26015d71a6f10f79d66341911878", "33e762c7ef856074595e394c1e047ad13ab3a7c425b1cea840cb4e35feff1aac", "678c3f338fef11b3b796956eadf38d3417bd52a69eb6a8bc87da8fc0aaeffffe"),
        Record(FeoriaTranslationCatalog.Entry("katavasia-tone4-four-odes:507e7252e342aa628cb2",
            "Ирмос, глас 4: Лук си́льных изнемо́же/ и немощству́ющии препоя́сашася силою:/ сего ради утверди́ся в Го́споде се́рдце мое.",
            "Ирмос, глас 4: Лук сильных ослабел, а немощные препоясались силой; поэтому утвердилось в Господе сердце мое.", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "katavasia-tone4-four-odes", 3, 1, "691da7dd998ae77da72455584e50d7402d606b1beb7da3db32b60d936f93a794", "507e7252e342aa628cb2c4e95ac4506613d2f479eb8565178ddd4eded5c3f342", "1f12bc93a41288e6aa3d4d0bee63779e4b3d24390aa5a0ad829d1091c835394e"),
        Record(FeoriaTranslationCatalog.Entry("cross-tone6-friday:523c67bfe3a632efe9c3",
            "Просте́ртие руки́, Го́споди, неудержа́нное, ко дре́внему вкуше́нию оте́мляй, ме́ртв на Дре́ве пожре́н бы́л еси́, спасти́ восхоте́вый: из ре́бр иска́паеши свя́занным оставле́ние.",
            "Отвращая безудержное протягивание руки к древнему вкушению, Ты, Господи, желая спасти, был умерщвлен и принесен в жертву на Древе; из Своего бока Ты источаешь прощение связанным.", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "cross-tone6-friday", 4, 1, "bd9ecbb7862d4ef4af7d4101ab907f4ee66cf4b76042a0342d858a777ef4d6e2", "523c67bfe3a632efe9c3cc21cda8e2db7eacfc0508dba4e3b0f9d828ceb1ec44", "b995790848b095b5fabc743169707455f4ee79611c917b4a4b9365d592d9b4f0"),
        Record(FeoriaTranslationCatalog.Entry("cross-tone6-friday:f17e2b3973a557cbf69e",
            "Страда́ти претерпе́л еси́, Преблаги́й, я́ко да разреши́ши на́с от страсте́й безслове́сия: же́лчь вкуси́л еси́, Влады́ко, источа́яй мне́ Боже́ственную сла́дость, умертви́лся еси́, Живо́т мне́ подава́я.",
            "Ты претерпел страдания, Всеблагой, чтобы освободить нас от неразумных страстей; Ты вкусил желчь, Владыка, источая мне Божественную сладость; Ты был умерщвлен, даруя мне жизнь.", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "cross-tone6-friday", 4, 2, "674e657c78e9abc5a5d446750a984b5c719a417184c5a988f675c4fd1a237cb2", "f17e2b3973a557cbf69ea292b80b4c812f4701f828ec51e413f1c6e7a93bb266", "9aeb5cd9412272e1f5f64664a397c1c93706d96beba5bcc85be381a899759e65"),
        Record(FeoriaTranslationCatalog.Entry("cross-tone6-friday:59cdae3119f48d6e4c48",
            "Мученичен: О́гнь Боже́ственныя любве́ в души́ слове́сней нося́ще, пла́мень пребеззако́ннующих угаси́ша: и просвети́тельныя свещы́ Христо́вы страстоте́рпцы яви́шася.",
            "Мученичен: Неся в разумной душе огонь Божественной любви, страстотерпцы Христа угасили пламя беззаконнейших и стали светильниками, несущими просвещение.", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "cross-tone6-friday", 4, 3, "b0aebd256354988fecbea7c060033da6a8a31875ebc8061b92dcdad577b48225", "59cdae3119f48d6e4c483c737c9d98258e7a2b18c45d07f566532893381c2925", "6b4c46e25242c6344969257bcae0398e62b2284053d436aea5c9e5701109255d"),
        Record(FeoriaTranslationCatalog.Entry("cross-tone6-friday:fb62a771a0fca9505bf5",
            "Мученичен: Боже́ственнии дру́зи Всецаря́, плотски́я себе́ отлучи́вше дру́жбы, устреми́шася ко вся́кому муче́нию кре́пко, и победи́вше, сла́вою венча́шася.",
            "Мученичен: Божественные друзья Царя всех, отрекшись от плотской дружбы, стойко устремились на всякое мучение и, победив, были увенчаны славой.", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "cross-tone6-friday", 4, 4, "41b16a046182d9be8f24fef5203e6c953ee95919b3807171905279ce5b97413b", "fb62a771a0fca9505bf5fda036c341592ee2d4a6227bbf246d6dfd7bba7f9485", "9bbe47018181f4e356b452fe67d32b152877ea6a6f3d56daff3d1d21d7326e2e"),
        Record(FeoriaTranslationCatalog.Entry("cross-tone6-friday:95845e96a718785ff2a8",
            "Богородичен: Кроме́ стра́сти роди́х Тя́, и ка́ко ви́жу Тя́ ны́не стра́сти причаща́ющася? Ка́ко терпи́ши сие́, взыва́ше Де́ва? Сы́не безнача́льне, сла́влю Твое́ долготерпе́ние.",
            "Богородичен: \"Без страдания Я родила Тебя, и как теперь вижу Тебя причастным страданию? Как Ты терпишь это? - восклицала Дева. - Безначальный Сын, славлю Твое долготерпение\".", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "cross-tone6-friday", 4, 5, "1ddcad7d0570d5be78a12a22873760d690b2d8dc700118999ada956b1f421f92", "95845e96a718785ff2a821fa77e7f3e196a6e8fe0eb94ddfe4b6c6e2b1bf551d", "88e6678ba511df6482422038a0ace7d4e2781b4199e1ae16731b9236087907c4"),
        Record(FeoriaTranslationCatalog.Entry("apostles-stachys-amplias-urban-narcissus-apelles-aristobulus-tone1:67297ee041b800561ea2",
            "Облиста́в на земли́ правды Солнце,/ я́коже лучи та́инственныя происпусти́ я́ве,/ Стахи́я же и Нарки́сса, Урва́на и Ампли́я, Аристову́ла и Апе́ллия,/ сущих во тьме просвещающия.",
            "Солнце правды, воссияв на земле, явно испустило как таинственные лучи Стахия и Наркисса, Урвана и Амплия, Аристовула и Апеллия, просвещающих пребывающих во тьме.", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "apostles-stachys-amplias-urban-narcissus-apelles-aristobulus-tone1", 4, 1, "970e9c4bc88a8582028c582569b7cbae7aa52ef6a60c7db430110ed150f8b1e2", "67297ee041b800561ea2dcfa9e486249bbb121e9b7394ee7bb4eddd76862738d", "c2969d33352f66250e66bea4bbe2632ea42b9efcbf31fd271f311bf091db5f12"),
        Record(FeoriaTranslationCatalog.Entry("apostles-stachys-amplias-urban-narcissus-apelles-aristobulus-tone1:183913dfb7841400dd3f",
            "Крепостию Божественнаго укрепляемь Духа,/ живущия во тьме сы́ны показа́л еси́ света, Ампли́е апостоле,/ совершая чудес дела́ преславная и упраждня́я де́монов полки́.",
            "Укрепляемый силой Божественного Духа, ты, апостол Амплий, сделал живущих во тьме сынами света, совершая славные чудеса и уничтожая полки демонов.", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "apostles-stachys-amplias-urban-narcissus-apelles-aristobulus-tone1", 4, 2, "6e800bdba143dfe00ad8102cd0a73ef5bb35ea867907e9caf219de375a13e0b5", "183913dfb7841400dd3f7c6c94c68ffcc76e2a14ded0446d966a2dcd93235b34", "8b89ed55ab2a29b5bf64de0e9d75fab9033fecde72885c2ea232ebb014f9eb7f"),
        Record(FeoriaTranslationCatalog.Entry("apostles-stachys-amplias-urban-narcissus-apelles-aristobulus-tone1:258b81754938d983417c",
            "Вод Боже́ственных испо́лнен,/ потекл еси́ я́коже струя, Урва́не, спаси́тельная,/ го́рькия и непи́тныя во́ды отгоняя,/ и напаяя благода́тию благоче́ствующих, преблаже́нне, полноту́.",
            "Исполненный Божественных вод, ты, Урван, потек как спасительный поток, отгоняя горькие и непригодные для питья воды и напояя благодатью все собрание благочестивых, преблаженный.", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "apostles-stachys-amplias-urban-narcissus-apelles-aristobulus-tone1", 4, 3, "b9688c9dcd8b247434661c8bd6b41467c0679adbe1c9554e4bf74da2d8a5567d", "258b81754938d983417cc910b34b391a95e0f0d2c604b0f9a383cea9ad53e9d0", "5d511273872eb382b7b54729ae90a575c2fb44d7bb0e07f6fa5d36bf78ff5d89"),
        Record(FeoriaTranslationCatalog.Entry("apostles-stachys-amplias-urban-narcissus-apelles-aristobulus-tone1:edcfb48757771ac91ddb",
            "Богородичен: Яви́лася еси́ А́нгелов преиму́щи, Влады́чице./ Оным бо Страшнаго во утробе несказа́нно вмести́ти сподо́билася еси́/ и на руках носи́ти я́коже Младенца дней же и лет древне́йша.",
            "Богородичен: Ты явилась выше Ангелов, Владычица, ибо удостоилась неизреченно вместить в Своем чреве Того, Кто страшен им, и носить на руках как Младенца Того, Кто древнее дней и лет.", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "apostles-stachys-amplias-urban-narcissus-apelles-aristobulus-tone1", 4, 4, "fc95bf774353258ca8409b3f63d7cbacec6365dd4079e5b02c7842dacafdba45", "edcfb48757771ac91ddb89b2881c677aa8bff52e22a9d6f7e9e5481f5db1d513", "156c6560094bf8e588ccde9528139c5ba46ce954c5e85aa877279beabc016cc8"),
        Record(FeoriaTranslationCatalog.Entry("martyr-epimachus-tone4:365ab31f44e23bdc86c8",
            "Безбожных неради́в преще́ния, к по́двигом ополчи́ся,/ дерзновенно вопия, благославный Епима́х:/ сла́ва си́ле Твое́й, Го́споди.",
            "Пренебрегая угрозами безбожных, славный Епимах вооружился для подвигов, дерзновенно восклицая: \"Слава силе Твоей, Господи!\"", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "martyr-epimachus-tone4", 4, 1, "a6bbbb74d2f701c53b6ef3093b1a3154b3d3d300869c9b158b7f6c7aeaf8044f", "365ab31f44e23bdc86c89ffa7054c3c1deb10d44546d8f754a9abf603054d77f", "ec080703fa1ff35c90f75644129c86b5ac4a55077390b526e88d31f87ceab5ab"),
        Record(FeoriaTranslationCatalog.Entry("martyr-epimachus-tone4:b161f69b22506bbfd18f",
            "Земная оплева́в, смертию Царство насле́дова славный Епима́х,/ верно вопия:/ сла́ва си́ле Твое́й, Го́споди.",
            "Презрев земное, славный Епимах через смерть унаследовал Царство, с верой восклицая: \"Слава силе Твоей, Господи!\"", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "martyr-epimachus-tone4", 4, 2, "14ac034ff68cebdb687f4f1df2c31c35af673feec7cac289ff30e6bcbab729e4", "b161f69b22506bbfd18fbdcef11256fea5fac26f418c1895d46e94a95189eafe", "e595cba609facd0b72d99c0b88961cd90510f216d6cb9a18072bd6b3613414a5"),
        Record(FeoriaTranslationCatalog.Entry("martyr-epimachus-tone4:f106d9fc050253353f93",
            "Иже со Отцем и Духом славословимаго в Вышних/ добропобедный Епима́х на три́знищи Го́спода всем неве́дущим пропове́да.",
            "На поприще мученичества добропобедный Епимах всем не знавшим Господа возвестил Его, прославляемого в вышних с Отцом и Духом.", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "martyr-epimachus-tone4", 4, 3, "d1de1cb5832922a46857346904950b51798ee2d3c1e6adf78983f013f14d03e9", "f106d9fc050253353f93f4ecda9f6e95f0ebee7fdc6da457a8bc24bfa0b79c48", "3c2be12d661bf467ab6e13ad32b462bfd5175db9515e5f8934ba747188b443d5"),
        Record(FeoriaTranslationCatalog.Entry("cross-tone6-friday:8724fffe3603c2469b3a",
            "Ме́ртв зри́шися на ло́бнем, умертви́в а́да стра́стию пло́ти Твоея́: ни ви́да ты́, Христе́, ни добро́ты име́л еси́ пове́шен, удобри́ти мя́ хотя́ я́ко Человеколю́бец.",
            "Ты виден мертвым на Лобном месте, умертвив ад страданием Своей плоти; повешенный, Ты, Христе, не имел ни вида, ни красоты, желая сделать меня прекрасным, как Человеколюбец.", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "cross-tone6-friday", 5, 1, "026b235b0b72ee7746676f6dfedc3fbba72cf608210ec9591f0e355635402baa", "8724fffe3603c2469b3a0982cbed060076cae661a1b993330e76c5af1e8b22d7", "0afaa43cc0ca9a187b936956f2d51ef2cb68dd288965d6c3fdc8fd7d46720e53"),
        Record(FeoriaTranslationCatalog.Entry("cross-tone6-friday:ebd7f51b2ea17f2c6cab",
            "Ада́ма пе́рваго пригвозди́ти хотя́ стра́стная любле́ния, гвоздьми́ пригвожда́ешися, и копие́м пробо́дься, пла́менному оружию возбраня́еши, Христе́, не возбрани́ти рабо́м Твои́м вхо́да.",
            "Желая пригвоздить страстные влечения первого Адама, Ты пригвождаешься гвоздями и, пронзенный копьем, запрещаешь пламенному мечу преграждать вход Твоим рабам, Христе.", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "cross-tone6-friday", 5, 2, "7a5c06320ee477d6c4599bd26e9dda4f5fd82917c1e5dcdc46be711f2d759dc8", "ebd7f51b2ea17f2c6cabfb7fa1a8b4c07ddeeffe9a7ffd8dc6f3cf201d268af2", "786aac9af65b32dfd5eb66166e8efcb08b28ebfd2d461a932a9d21f24246cba2"),
        Record(FeoriaTranslationCatalog.Entry("cross-tone6-friday:4c56deaeb6dfffa14dfb",
            "Мученичен: После́дствующе страсте́м Влады́чним, ли́цы му́ченичестии на Дре́ве пригвожда́ются, и рука́ми ку́пно оте́млются, и нога́ми к стези́ честна́го муче́ния Боже́ственне исправля́еми.",
            "Мученичен: Следуя страданиям Владыки, сонмы мучеников пригвождаются ко древу и лишаются рук, а ноги их Бог направляет на путь достойного почитания мученичества.", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "cross-tone6-friday", 5, 3, "d0e839b91f167997f393e70acd3ae81e50f050dd71e6885e46d29fcce497d953", "4c56deaeb6dfffa14dfb4ed124b32511f9645c5c3207b09e35592a013667973f", "06c08efcaac1fd320d580a23a58f53f010dc1d28ca3ce27023769cbd88b8ebdf"),
        Record(FeoriaTranslationCatalog.Entry("cross-tone6-friday:85195b0e746bf4bdf984",
            "Мученичен: Умо́м соверше́нным, ума́ го́рдаго вознося́щася де́рзостию низложи́сте соверше́нно смири́вшеся в подража́нии, вся́ возне́сшаго смире́нием се́рдца, Христо́вы му́ченицы.",
            "Мученичен: Христовы мученики, совершенным умом вы совершенно низложили гордый ум того, кто превозносится дерзостью, смирившись в подражание Возвысившему всех смирением сердца.", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "cross-tone6-friday", 5, 4, "9da4514e87c88c0ea429ccd46c5b01b3a7d6e336d2fe435d4b6eaf2921e0c7cd", "85195b0e746bf4bdf984becef423776c281a3e3187f804aa35831a97f36bb5ac", "40e0cdfcd9c5949d84509e6640b9d598b0571fecc29eb4249d7ae27fa27783b6"),
        Record(FeoriaTranslationCatalog.Entry("cross-tone6-friday:cbab36e0518514a0b142",
            "Богородичен: От ко́рене, Де́во, Иессе́ова прозяба́еши, и я́ко цве́т произно́сиши Насади́теля ми́ру, о́трасли безбо́жия изсуши́вша Боже́ственным са́дом Креста́, его́же пло́тию прия́т.",
            "Богородичен: Ты произрастаешь, Дева, от корня Иессеева и, словно цветок, приносишь Насадителя мира, иссушившего побеги безбожия Божественным насаждением Креста, который Он принял плотью.", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "cross-tone6-friday", 5, 5, "aaa947c0565b47f1b4539a4a1cb0b8fee2665b0a4e75d3693af22540f737ce9a", "cbab36e0518514a0b14221d4074604c4c11877231e0d0f53365067d957507468", "140da0dcdc4658cd76f40ccb88267ae4002192d94756db1c0a5028a0facb46ec"),
        Record(FeoriaTranslationCatalog.Entry("apostles-stachys-amplias-urban-narcissus-apelles-aristobulus-tone1:868210c7cf9e884a8312",
            "Пастыря добраго Богоизбра́нныя о́вцы/ посреди волко́в от Него я́ве по́слани быша,/ сия́ укроща́юще и приводяще ко ограде мысленней верою.",
            "Богоизбранные овцы доброго Пастыря были явно посланы Им среди волков, укрощая их и с верой приводя в духовную ограду.", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "apostles-stachys-amplias-urban-narcissus-apelles-aristobulus-tone1", 5, 1, "4a2fc66915cf28d799308326da6a388019add55300abcdf31e3527a96bfb7c14", "868210c7cf9e884a8312e81b0d76d6b9d05619fd778408463f994a5ef9d8560d", "0734940390353d690db06480d5723bcd28e6421562b363e92f52f1f5a57864c0"),
        Record(FeoriaTranslationCatalog.Entry("apostles-stachys-amplias-urban-narcissus-apelles-aristobulus-tone1:2888d7530a299ce52eda",
            "Великий тя Андрей Византи́и поста́ви епископа,/ и́же та́мо верно плавающия, Стахи́е священнейше,/ и управляющаго к приста́нищем тихим Боже́ственною благода́тию.",
            "Великий Андрей поставил тебя епископом Византия, святейший Стахий, чтобы ты Божественной благодатью направлял там с верой плывущих к тихим пристаням.", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "apostles-stachys-amplias-urban-narcissus-apelles-aristobulus-tone1", 5, 2, "ff8b7e8388786ef615765c35452c8fc93cc53986d0602c4ea6c846667a4f5e81", "2888d7530a299ce52eda93ce6bd8c607df5af48c61ec864308f50cecd9837beb", "6f5079bd78bfaa7e4ffc4ffd6844e745da368d77823baed988484d0d9796dbb9"),
        Record(FeoriaTranslationCatalog.Entry("apostles-stachys-amplias-urban-narcissus-apelles-aristobulus-tone1:6fe91088c4a9ec0b6df0",
            "Я́коже многоце́нен камень, тя имя́ше, краеугольный, Иракли́йская честна́я Церковь,/ укрепля́юща, Апе́ллие блаже́нне, сию́ словом Истины./ Тем досто́йно почитаем тя.",
            "Как драгоценный краеугольный камень имела тебя почтенная Церковь Ираклии, блаженный Апеллий, укрепляющего ее словом Истины. Поэтому достойно чтим тебя.", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "apostles-stachys-amplias-urban-narcissus-apelles-aristobulus-tone1", 5, 3, "dfefea36ed72ee039329284b4d04355482dd682ee7a48604573d2e0e35b9a84f", "6fe91088c4a9ec0b6df0d0ec23e0ccbeee294699b08ca4ca069c5ac32a31c8a9", "6ad591bcf50d053249981a79679765858cbec865299a8ba548a6751ffcfff6cd"),
        Record(FeoriaTranslationCatalog.Entry("apostles-stachys-amplias-urban-narcissus-apelles-aristobulus-tone1:b51bc79ba5eb33b998d0",
            "Богородичен: Зачала́ еси́ па́че слова Слово и родила́ еси́, Всепетая,/ Егóже Отец из чрева роди́ прежде веко́в, Чи́стая./ Темже я́ко Сего Матерь Тя до́лжно ублажа́ем.",
            "Богородичен: Ты зачала превыше слова и родила Слово, Всепетая, Которого Отец родил из Своего лона прежде веков, Чистая. Поэтому мы, как подобает, прославляем Тебя как Его Матерь.", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "apostles-stachys-amplias-urban-narcissus-apelles-aristobulus-tone1", 5, 4, "0d76742e47ae411c2977ce93c7413fb3c30214324d05c55c14ebde5758a671cd", "b51bc79ba5eb33b998d0efdd911ab6a9ab8a61fe1bde1222072ed572362d792e", "18f2b202ac1420a8fb336173aac2eee6a7c1f697c1a3fd213d0d68eba9d86634"),
        Record(FeoriaTranslationCatalog.Entry("martyr-epimachus-tone4:f730625346831d1f5e29",
            "Защити́вся благода́ти оружием Креста,/ нечестивым вопияше мученик:/ меч же и огнь не отсече́т мя Христовы любве́.",
            "Защитившись благодатным оружием Креста, мученик восклицал нечестивым: \"Ни меч, ни огонь не отлучат меня от любви Христа!\"", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "martyr-epimachus-tone4", 5, 1, "260857d10f522df703fd7b87f7ee75a14576ebd8498bbb4892820df1c73b0ad8", "f730625346831d1f5e291015a931342b2a0d99e4be7a7d3905da7c1bcb66f8a5", "be4e8a2e73554fc1fc404145dec0db85d99df9053fd042fb1851aaed8abe1b02"),
        Record(FeoriaTranslationCatalog.Entry("martyr-epimachus-tone4:143c9f71d39dbb50d108",
            "Благославный Епима́х, суди́щу предстоя́ беззако́ннующих,/ вопияше благоде́рзостне:/ земли́ и Небесе́ бо́зи несотворшии, нечести́вии да погибнут.",
            "Стоя перед судилищем беззаконных, славный Епимах смело восклицал: \"Да погибнут нечестивые боги, не сотворившие земли и неба!\"", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "martyr-epimachus-tone4", 5, 2, "f90d879e41be244b301a33e10880ee58b49341aaa94933f09fef10464a2700e7", "143c9f71d39dbb50d108d5e87d7c6494278870eb12e414a87ab4485f129f622a", "84773bc9075d2195782a14b258bb9fecb320361ee69f8abdc820d1abd8ff5d8b"),
        Record(FeoriaTranslationCatalog.Entry("martyr-epimachus-tone4:a97f58d65884ca5b5180",
            "Благославный Епимах, от Бо́га вдохну́вся,/ Отца, Слова и Свята́го Ду́ха во едином естестве́/ неве́дущим Троицу проповеда.",
            "Вдохновленный Богом, славный Епимах проповедовал не знавшим Троицу Отца, Слово и Святого Духа в единой природе.", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "martyr-epimachus-tone4", 5, 3, "8b33ba714ba320a19057ec1b9091259a5a15f6e66217c5e2a2e7c3ce85aee0a7", "a97f58d65884ca5b5180f4289207422cbb737374016df870906ba20982a0783b", "7b03b1fdc2bea13d0a6bce91c746e1675ba15a7b7f77534e5cf963cde0160f8c"),
        Record(FeoriaTranslationCatalog.Entry("martyr-epimachus-tone4:278d75fcedf81d42b1b6",
            "Богородичен: Кто изрещи́ возможет Рождества Твоего́, Чи́стая,/ па́че слова преславный образ,/ естеством бо Бо́га воплоще́нна па́че слова родила́ еси́.",
            "Богородичен: Кто сможет выразить, Чистая, дивный образ того, как Ты родила, превосходящий всякое слово? Ибо Ты невыразимым образом родила воплотившегося Того, Кто по природе Бог.", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "martyr-epimachus-tone4", 5, 4, "eeb905fa7dbc2daaddee6a94a004c63ee5acfc4db6a4c99610e0820a0ec3ba69", "278d75fcedf81d42b1b6f7d4d727ca3f74f8e63d84c076c7a55e991e9e4b7a7d", "5faacfffdb2582a9d60fa84f96433ada63547f9fe3bd7fcb39cea78a47c7d26a"),
        Record(FeoriaTranslationCatalog.Entry("cross-tone6-friday:8fcb0a9a75400a6da5f8",
            "Пременя́я ру́це дре́вле Иа́ков прообразова́ше Кре́ст, благословля́я о́троки. Те́мже Вы́шний на того́ восходя́й, кля́твы дре́вния реши́ши челове́чество: и источа́еши ны́не благослове́ние, благословя́щым Тя́, Еди́не благослове́нне, и Соде́телю Преблаги́й.",
            "Перекрещивая руки, Иаков в древности прообразовал Крест, благословляя детей. Поэтому Ты, Всевышний, восходя на него, освобождаешь человечество от древнего проклятия и теперь источаешь благословение благословляющим Тебя, Единый Благословенный и Всеблагой Создатель.", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "cross-tone6-friday", 6, 1, "aec4ca7d02828e0b70734186a655efb7fc81dda891dd380b128570ac30669583", "8fcb0a9a75400a6da5f83c36ff1aea23502ecdd676cf450166a4b31e7036422c", "1a9b61e005cc945483f90c2ad607ccbea52192f4d179313c852152ede2cd2b6e"),
        Record(FeoriaTranslationCatalog.Entry("cross-tone6-friday:aab7535dd88a6cfbb146",
            "Твою́ стра́сть прообразу́яй, Сло́ве, вели́кий Моисе́й вознесе́ дре́вле ме́днаго зми́я на дре́во, оте́мляй зря́щыя от ядови́таго угрызе́ния змии́на: и́бо, Влады́ко, ра́спяту бы́вшу Ти́, врежде́ния змии́наго богоме́рзскаго вси́ ве́рнии изба́вихомся.",
            "Прообразуя Твои страдания, Слово, великий Моисей некогда поднял медного змея на древо, избавляя взирающих на него от ядовитого змеиного укуса: ибо, когда Ты, Владыка, был распят, все мы, верные, избавились от вреда богомерзкого змея.", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "cross-tone6-friday", 6, 2, "fb44dd8329c9e59b20f8058e2770fb417b3f64c5b4c4438f2294027a0491bb8a", "aab7535dd88a6cfbb146d3d418c30260ae94495cd045ababc331c4278f1e217a", "a7c9994738cc83746d0d87adbd4079d8b24a529c6dd0a82dcd4ce707e87024b0"),
        Record(FeoriaTranslationCatalog.Entry("cross-tone6-friday:64738c4d0d0184ee5b50",
            "Мученичен: Я́коже ино́му стра́ждущу Боже́ственнии дре́вле и честни́и страда́льцы бя́ху страда́льчествующе, предзря́ще воздая́ния ве́чная и ра́дование. моли́твами и́х, Христе́ Ще́дре, воспева́ющыя Тя́ изба́ви от искуше́ний, и грехо́в, и обстоя́ний.",
            "Мученичен: Древние святые и почитаемые страдальцы претерпевали мучения, словно страдал кто-то другой, предвидя вечное воздаяние и радость. По их молитвам, милосердный Христе, избавь воспевающих Тебя от искушений, грехов и бедствий.", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "cross-tone6-friday", 6, 3, "ea17403ddd00810252d9e327cee0aef11d9387bff1275af8e7489b28bb1045f3", "64738c4d0d0184ee5b50e1daa25d2aa15d187f321b7b9b8c24e5c2e7baffc095", "d578e82300552e5fb89301518a0c9fd0e07bb958bcdc1575d3d4427f56fdd208"),
        Record(FeoriaTranslationCatalog.Entry("cross-tone6-friday:15eac781fb003df58332",
            "Мученичен: Пото́ки уста́виша пре́лести, струя́ми крове́й, честни́и и Боже́ственнии страстоте́рпцы, и исто́чницы вои́стинну яви́шася, ве́рным богове́дения точа́ще во́ду. Моли́твами и́х, Спа́се ми́ра, одожди́ оставле́ние все́м, и живо́т, и очище́ние грехо́в, и ве́лию ми́лость.",
            "Мученичен: Потоками крови святые и почитаемые страстотерпцы остановили потоки заблуждения и поистине стали источниками, изливающими верным воду богопознания. По их молитвам, Спаситель мира, ниспошли всем дождем прощение, жизнь, очищение грехов и великую милость.", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "cross-tone6-friday", 6, 4, "62a38a09c1598969de4389d61134d89818181fd71ed764515c65847a4064946d", "15eac781fb003df58332e3d2c64680630446cab861846af58a734040d62fe44e", "21f5b7e953f95c96af96ed20721777498cf5d3af75ba09f59b235cacdb4cefb6"),
        Record(FeoriaTranslationCatalog.Entry("cross-tone6-friday:6ee051be214871ef9a29",
            "Богородичен: Па́стыря пе́рваго и Влады́ку, воздви́жена на Дре́ве зря́щи А́гница, пла́чущи ма́терски вопия́ше: что́ сие́, Ча́до, но́вое та́инство? ка́ко безсме́ртен по существу́ сы́й сме́рть прия́л еси́, челове́ки хотя́ из тли́ изба́вити?",
            "Богородичен: Видя Первого Пастыря и Владыку вознесенным на Древо, Агница, плача, по-матерински восклицала: \"Что это за новое таинство, Дитя? Как Ты, бессмертный по существу, принял смерть, желая избавить людей от тления?\"", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "cross-tone6-friday", 6, 5, "1ee5ca26e1b60a1d43d77a6b897ece9dac7f8a240768a64416e037921af23fb7", "6ee051be214871ef9a29df6006feff5c7821561cde297f01e5384ad26e2c9e0a", "ffb087ffb826e32fa5b46f67c363c618564c66e1f2c60f7c5327afadf9eaebbf"),
        Record(FeoriaTranslationCatalog.Entry("apostles-stachys-amplias-urban-narcissus-apelles-aristobulus-tone1:061531c183aafe84e736",
            "Моря́ язы́ков возмутивше Божественными восхождении,/ спасо́сте древле в го́рцем мо́ри пото́пльшияся/ и приведо́сте Изба́вителю спасшияся, Богоблаженнии.",
            "Своими Божественными странствиями вы взволновали моря народов, спасли некогда утонувших в горьком море и привели спасенных к Избавителю, Богом ублаженные.", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "apostles-stachys-amplias-urban-narcissus-apelles-aristobulus-tone1", 6, 1, "41a2dec864c2e772d871adf355cc5c95bafbe25f585ed9485eebe35c4212df19", "061531c183aafe84e7364718ee7ef748344d3575a1b5764490aa062762ea7a93", "927968b17caa7f53f595259729d25674c5b3e4c6d1ee06d9b9b614a3d0e2101b"),
        Record(FeoriaTranslationCatalog.Entry("apostles-stachys-amplias-urban-narcissus-apelles-aristobulus-tone1:22d372a57a9fa63e697d",
            "Милости Воли́теля Бо́га проповедал еси́/ и ле́сти свободи́л еси́, Боже́ственный Нарки́ссе, ду́ши благочестивых,/ великий быв афи́нян председатель и насади́тель садо́в кра́сных, Богоблаженне.",
            "Ты проповедал Бога, желающего милости, и освободил от заблуждения души благочестивых, святой Наркисс, став великим предстоятелем афинян и насадителем прекрасных садов, Богом ублаженный.", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "apostles-stachys-amplias-urban-narcissus-apelles-aristobulus-tone1", 6, 2, "f1e4d3ac275427160c9a78ace5d0af354996bca99b18dfbdf7d15288760067b7", "22d372a57a9fa63e697df7a52e9fd73c38c0623095cd65cece0853ab1f27f8bf", "1102c1c7a50016515d2b25e45a0ebec4d321eca4de282149f70e64522dee19d1"),
        Record(FeoriaTranslationCatalog.Entry("apostles-stachys-amplias-urban-narcissus-apelles-aristobulus-tone1:7eb72b60d7caa83c1e5a",
            "Боже́ственный Урва́н, слово жизноточное и благода́ть врачеваний источи́в,/ привлече́ люди к просвещению Божественнаго разума,/ я́ко подражатель Воплотившагося и мир Спасшаго.",
            "Святой Урван, источив животворное слово и благодать исцелений, привлек людей к просвещению Божественным знанием, как подражатель Воплотившегося и Спасшего мир.", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "apostles-stachys-amplias-urban-narcissus-apelles-aristobulus-tone1", 6, 3, "5dae18cd39c1eb7cb2e3d0aabb107b3ff69063ac1290945ac78714a5c4f20c00", "7eb72b60d7caa83c1e5aa64377b5de1e29b519f5c6d6f7c2569e5688cb564924", "d62415ab611528849fe6e142f8ed87454c2940f4c085c2cf920008068463f091"),
        Record(FeoriaTranslationCatalog.Entry("apostles-stachys-amplias-urban-narcissus-apelles-aristobulus-tone1:53259ad7b821f4230807",
            "Богородичен: Поем Тя, Еюже оправди́хомся,/ и́же пе́рвее осужде́ннии, и совокупи́хомся невещественным служителем, и рая́ сподо́бихомся,/ в жена́х благословенная, Богорадованная.",
            "Богородичен: Воспеваем Тебя, через Которую мы, прежде осужденные, были оправданы, соединились с бесплотными служителями и удостоились рая, Благословенная среди женщин, Обрадованная Богом.", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "apostles-stachys-amplias-urban-narcissus-apelles-aristobulus-tone1", 6, 4, "f9a98dd50079ed7bfdf82a770029827e92106de9bb4a99e5b5bb601ad4a1fc7e", "53259ad7b821f4230807b0c15944e17e68defd0ad508117548bfb3cd9f213b18", "193dc0926b2db24d8b19fe9b55ed3d7b5177c04709606ba485820290f4972dcd"),
        Record(FeoriaTranslationCatalog.Entry("martyr-epimachus-tone4:b4f4b3ab4d8ce3d7ed73",
            "Оста́ви яже в мире и мир Епима́х,/ и тело му́кам мужественно предаде́ за Владыку,/ и Христов наследник бысть.",
            "Епимах оставил мир и все мирское, мужественно предал тело мучениям за Владыку и стал наследником Христа.", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "martyr-epimachus-tone4", 6, 1, "c533e0a30573412ebae76644b935ed9e3653d0e8970533dd6a511230f66f33c1", "b4f4b3ab4d8ce3d7ed73693e2ae6b31954a9f8204e0dc9b8397ef1996f55dddc", "89cffc1b7294e95f4583e175758046506cc745611fe6ddfd1e4a522b601e507e"),
        Record(FeoriaTranslationCatalog.Entry("martyr-epimachus-tone4:79f3424c7f9f4975b454",
            "Упраздни́ и́долов лесть Епима́х и славы сподо́бися истинныя,/ прие́м врачеваний благода́ть, от нихже вси ве́рнии почерпаем.",
            "Епимах уничтожил обман идолов и удостоился истинной славы, приняв благодать исцелений, из которых все мы, верные, черпаем.", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "martyr-epimachus-tone4", 6, 2, "dfce7cae4dcb5c875ff8b783c5f4d7df1ab46fce6e5e7df14fc6da7b2df0cf72", "79f3424c7f9f4975b4541c4c01feb1a222825a05d6968598e6827d53be73f266", "006d24d7a4624975e114cc2391d0dd6a0f32484073fe90cb1bd87423831821cf"),
        Record(FeoriaTranslationCatalog.Entry("martyr-epimachus-tone4:bde84123bd0432bd36ef",
            "Приобщи́вся Христовым страсте́м Епима́х/ силою распеншагося плотию Христа́ Бо́га/ и венцы славы от Него я́ко верен прия́т.",
            "Епимах приобщился страданиям Христа силой распятого плотью Христа Бога и, как верный, принял от Него венцы славы.", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "martyr-epimachus-tone4", 6, 3, "1682dc07ff6f52c7d5a43ea5e4694c063186bf2cea0b1d45302211af0e653389", "bde84123bd0432bd36ef535bee73e5127c6ffa81678c6398e114ea8b6f56740b", "85c2ba3348022e0034251ab12ad0f2b5a8775826bc53481c23481228571d751f"),
        Record(FeoriaTranslationCatalog.Entry("martyr-epimachus-tone4:c567505dd53539afc375",
            "Богородичен: Моли о рабе́х Твоих, Де́во Богоро́дице,/ из Тебе́ воплощшагося Бо́га на́шего,/ я́ко Тя и едину Предстательницу нашу ве́мы.",
            "Богородичен: Моли о Твоих рабах, Дева Богородица, нашего Бога, воплотившегося от Тебя, ибо Тебя одну мы знаем нашей Заступницей.", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "martyr-epimachus-tone4", 6, 4, "47fa40ff0c0bbea779c2a6919f6e3f212d46fab1b7a2b80a14ec499e1cbca41b", "c567505dd53539afc375d2e9e8e7ff81864a596d9870602e544cedfe28f50376", "ad9626108fcc8e9ed1c4ae40e0bf31e7627c79dc90c32e4d3838598dfd0d1f5d"),
        Record(FeoriaTranslationCatalog.Entry("katavasia-tone4-four-odes:f63e8d90493c4e4c8127",
            "Ирмос, глас 4: Возопи́, прообразу́я погребение тридне́вное, пророк Иона,/ в ки́те моля́ся:/ от тли изба́ви мя, Иисусе, Царю Сил.",
            "Ирмос, глас 4: Прообразуя тридневное погребение, пророк Иона, молясь во чреве кита, воскликнул: \"От тления избавь меня, Иисусе, Царь Сил!\"", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "katavasia-tone4-four-odes", 6, 1, "8e33cd7766f73e48512a9a4576c13c2d3be536539ce96fccb2afb93b750c4db1", "f63e8d90493c4e4c81275e8b7b275e2b62a3ef581c5b05131343430b17c021a2", "260aa5f1d28918cad0ffd30f2e03d77271a5488cb8ee994a4fb1042c43a6cc09"),
        Record(FeoriaTranslationCatalog.Entry("cross-tone6-friday:85a2c990652fe2f1b1c3",
            "Егда́ Тя на Кресте́ собо́р евре́йский осуди́, зря́щи земля́ ужасе́ся: со́лнце све́т сво́й сокры́, и су́щии во тьме́ све́т ви́деша, пою́ще: Изба́вителю Бо́же, благослове́н еси́.",
            "Когда иудейское собрание осудило Тебя на Крест, земля, видя это, ужаснулась; солнце скрыло свой свет, и пребывающие во тьме увидели свет, воспевая: \"Бог Избавитель, благословен Ты!\"", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "cross-tone6-friday", 7, 1, "7c09a84ccaaf2005cd890778d0cd087427d60eeb344f0001f0701a97d9eb6c45", "85a2c990652fe2f1b1c31f9a8a7c606bcd32e02705285527b965dd7d85fcdbf7", "bb27d8c24439e8e283199523f2205fb4d51471fbcdcd72be3fbd105198b23fb6"),
        Record(FeoriaTranslationCatalog.Entry("cross-tone6-friday:1c2211e8d2f310e549a2",
            "Досажде́ние претерпе́л еси́, Спа́се, тро́стию бие́мь, и те́рниями я́ко Ца́рь, во́лею, Христе́ Бо́же, венчава́емь, на спасе́ние на́с пою́щих: Изба́вителю Бо́же, благослове́н еси́.",
            "Ты претерпел поругание, Спаситель, тростью избиваемый и добровольно увенчиваемый терниями как Царь, Христе Боже, ради спасения нас, воспевающих: \"Бог Избавитель, благословен Ты!\"", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "cross-tone6-friday", 7, 2, "209abefa59b4f1d084752a0070f5910bbb813dfcdf6ee5717bfbb8c94b100ca0", "1c2211e8d2f310e549a2a456a47b501d1f7b9643592eadfccade77b6a48b8c69", "73a49097f8f836653322c82359f183c3f702be3cc271aaa5be01042f44a61ab2"),
        Record(FeoriaTranslationCatalog.Entry("cross-tone6-friday:4c4d5f13fb4cf5306523",
            "Мученичен: Связу́етеся, всю́ диа́волю пре́лесть всехва́льнии му́ченицы реша́юще я́ве: терпите́ му́ки и сме́рть непра́ведную: жи́зни жела́юще го́рния, и вопию́ще: Изба́вителю Бо́же, благослове́н еси́.",
            "Мученичен: Вас связывают, достойные всякой хвалы мученики, а вы явно разрушаете весь обман дьявола; терпите мучения и неправедную смерть, желая жизни в вышних и восклицая: \"Бог Избавитель, благословен Ты!\"", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "cross-tone6-friday", 7, 3, "e03e59a290d75be896d70c7512eabf60ed16ed61085b664281b69ff2c5dd3028", "4c4d5f13fb4cf5306523978fe09cd2042b04c0c708197c45ea6d37a77a670bce", "14017e0063eea00543010908e413bc6527c774e6e487c77e519b0a2a3a328833"),
        Record(FeoriaTranslationCatalog.Entry("cross-tone6-friday:5a6f427290a04a411185",
            "Мученичен: Ста́сте посреде́ пла́мене, всехва́льнии му́ченицы, пре́лесть попаля́юще я́ве, и ороше́нием Боже́ственныя благода́ти не опали́вшеся, вопие́те пою́ще: Изба́вителю Бо́же, благослове́н еси́.",
            "Мученичен: Вы встали среди пламени, достойные всякой хвалы мученики, явно сжигая заблуждение, и, не опалившись благодаря орошению Божественной благодати, воспевая, восклицаете: \"Бог Избавитель, благословен Ты!\"", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "cross-tone6-friday", 7, 4, "0c846d84ade987174ea57f5b0003557f94632abd73074812ecd86bd926e4ff41", "5a6f427290a04a411185c78f3e1528a2d4e85bece6922f9edd49a4bdc270e216", "aaa388d658458df26f060acbd744e66cc4653d370e26b609e5d379a8bfc2acf6"),
        Record(FeoriaTranslationCatalog.Entry("cross-tone6-friday:61a08737792190264f08",
            "Богородичен: Распина́ешися хотя́й, безнача́льне Сы́не, Богоро́дица взыва́ше зря́щи Тя́: печа́лию души́ ны́не погружа́юся, умира́еши подая́й жи́знь пою́щым: Изба́вителю Бо́же, благослове́н еси́.",
            "Богородичен: \"Ты добровольно распинаешься, Безначальный Сын, - восклицала Богородица, видя Тебя. - Ныне душой погружаюсь в печаль: умираешь Ты, дарующий жизнь воспевающим: Бог Избавитель, благословен Ты!\"", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "cross-tone6-friday", 7, 5, "12cbd26096fb365e20710ddeb79f89c28b2a2965c2a323474b70a64b99cb9c41", "61a08737792190264f0874daf05baa65a2d741314a7ad25623f33f7c9c41d8ba", "7c26cb982d707b938954383bd8beaa905536b9a7843786839189b7d166e52ad3"),
        Record(FeoriaTranslationCatalog.Entry("apostles-stachys-amplias-urban-narcissus-apelles-aristobulus-tone1:b5b38fba94b834527163",
            "Терпением напа́стей изба́вистеся врага́, искушающаго вы,/ ту́чами же слова животнаго, славнии апостоли, весь угаси́сте пламень ле́сти, зовуще:/ хвальный и превозносимый отец на́ших Бо́же, благослове́н еси́.",
            "Терпением бедствий вы избавились от искушающего вас врага, славные апостолы, а ливнями животворного слова угасили все пламя заблуждения, взывая: \"Достойный хвалы и превозносимый Бог отцов наших, благословен Ты!\"", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "apostles-stachys-amplias-urban-narcissus-apelles-aristobulus-tone1", 7, 1, "55ed4bced2ee485013d95a0da70b2209f7424386a737d0a67407dfb78fe32a31", "b5b38fba94b8345271636338de326682aea05c1aaddc4fc74b3629cb8f1d8e59", "903032e28587841ed0abd6db3ed87d7e366ad948835350633fea1903b4655558"),
        Record(FeoriaTranslationCatalog.Entry("apostles-stachys-amplias-urban-narcissus-apelles-aristobulus-tone1:cdff3704f51adab67633",
            "Пресветло и изрядно совещал еси́/ и совершенно твоя́, Аристову́ле, ученики, блаже́нне, наказа́л еси́,/ я́ко Ипостасную Мудрость имея, тя наказу́ющу хвальнаго возвещати/ отцев Бо́га и препрославленна.",
            "Ты наставлял светло и превосходно и в совершенстве научил своих учеников, блаженный Аристовул, имея Саму Ипостасную Премудрость, наставляющую тебя возвещать Бога отцов, достойного хвалы и величайшей славы.", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "apostles-stachys-amplias-urban-narcissus-apelles-aristobulus-tone1", 7, 2, "07c77cd484dcecc6b4599f91cdf519c147b3ed241fdf14457d329e4b6e4925a5", "cdff3704f51adab67633dfed6ffed2ced53a6d6666718d7863350382ac6307e1", "e9d6e1672d35912e68155243575e2f1ec7d090d841d6ec256c71573b6c73daf1"),
        Record(FeoriaTranslationCatalog.Entry("apostles-stachys-amplias-urban-narcissus-apelles-aristobulus-tone1:8add96a9458cd69f4679",
            "Верных священное совокупление священнейшими гла́сы блажи́т тя, Апе́ллие,/ кончи́ну бо блаже́нну имел еси́, житие же А́нгельское,/ поя́ всегда хва́льнаго отцев Бо́га и препрославленна.",
            "Священное собрание верных святыми голосами прославляет тебя, Апеллий, ибо блаженной была твоя кончина, а жизнь - ангельской, и ты всегда воспевал Бога отцов, достойного хвалы и величайшей славы.", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "apostles-stachys-amplias-urban-narcissus-apelles-aristobulus-tone1", 7, 3, "244ac9301973bda522085c614eeb52d80c6240a0378c055013baad7c53c0d4bc", "8add96a9458cd69f4679a731e5d8096bfeb1605905a590016493305a6cf59a0b", "60ea273f3b07854458ce3906f16555b8d24431591a5bc85b86023f5898fc2249"),
        Record(FeoriaTranslationCatalog.Entry("apostles-stachys-amplias-urban-narcissus-apelles-aristobulus-tone1:9035b05c10d96b70ed81",
            "Богородичен: Изба́ви ны от напастей, и скорбе́й, и печалей различных,/ и язы́ков нашествия, Влады́чице Всепетая,/ я́ко да Тя сла́вим и Сыну Твое́му взываем:/ хвальный отец на́ших Бо́же, благослове́н еси́.",
            "Богородичен: Избавь нас от бедствий, скорбей, разных печалей и нашествия народов, Всепетая Владычица, чтобы мы славили Тебя и восклицали Твоему Сыну: \"Достойный хвалы Бог отцов наших, благословен Ты!\"", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "apostles-stachys-amplias-urban-narcissus-apelles-aristobulus-tone1", 7, 4, "511ba621bf8b9b526891e5000242131f2f5a1b000695777a324ea5e567093b07", "9035b05c10d96b70ed8197d6eaf69efd42b7bf07c050f7d41be5284540fba066", "4c640fc3571ed5a01889d88c096e6d6cf2c12fafbb7e70da0f856f05ffaba5d8"),
        Record(FeoriaTranslationCatalog.Entry("martyr-epimachus-tone4:5fc13c127dfda17895c3",
            "Со огне́м лесть попирая мужески,/ Распе́ншемуся добропобедный вопияше Епима́х:/ отец на́ших Бо́же, благослове́н еси́.",
            "Мужественно попирая огонь и заблуждение, добропобедный Епимах восклицал Распятому: \"Бог отцов наших, благословен Ты!\"", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "martyr-epimachus-tone4", 7, 1, "4afd783b7bb4733cd69527947727cb2b87aabad4d53f7d6a9ce215ef86833410", "5fc13c127dfda17895c3e2cd3234483a0ad2d00f5ff06d0a73ec0d422475a296", "2ce2156888cbb062100cae2dc6e3a7a8ea70563152e7f13eb932f27a40b2e9a3"),
        Record(FeoriaTranslationCatalog.Entry("martyr-epimachus-tone4:bd9bdd4eff76582502f1",
            "Не убояся пла́мене, ниже́ звере́й ди́виих, ниже́ мук непобеди́мый Епима́х, зовы́й:/ отец на́ших Бо́же, благослове́н еси́.",
            "Ни пламени, ни диких зверей, ни мучений не испугался непобедимый Епимах, взывая: \"Бог отцов наших, благословен Ты!\"", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "martyr-epimachus-tone4", 7, 2, "b42cad8296f41f6fbe26bb50e7ab1c66130775db2cb04be24b79d4c9ec1c91d6", "bd9bdd4eff76582502f1d519db3b7f60f58bd76d0a747c0decb709408ea55162", "b27649bdc81c63180b55fd6e6c055bf345cdd550a0fa59bb24811dd6eb3ff54d"),
        Record(FeoriaTranslationCatalog.Entry("martyr-epimachus-tone4:504c01ef5b64dce41827",
            "Со Отцем Слова и Всесвята́го Ду́ха не ве́дущим Епима́х проповедуя, взываше:/ отец на́ших Бо́же, благослове́н еси́.",
            "Проповедуя не знающим Слово с Отцом и Всесвятого Духа, Епимах восклицал: \"Бог отцов наших, благословен Ты!\"", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "martyr-epimachus-tone4", 7, 3, "97d0be8df444dbf566452bd2108fac9ae91ec5d3946072e66e95d51d66001aa6", "504c01ef5b64dce41827a7f7cc80a3540c64ee65efa8d99462c6e20cbf863d27", "aa2fcc8d30ca4380e60747929a8f8c35baf2dab548d67056eaa428de5df9fd72"),
        Record(FeoriaTranslationCatalog.Entry("martyr-epimachus-tone4:f650d71a2842ff5b3187",
            "Богородичен: Неопа́льною купино́ю и росодательною пе́щию/ Ты пронаписавшаяся, Ма́ти Чи́стая,/ несказа́нно бо родила́ еси́ воплощеннаго Христа́ Бо́га, Благословенная.",
            "Богородичен: Тебя предызображали несгорающая купина и печь, подающая росу, Чистая Матерь, ибо Ты неизреченно родила воплотившегося Христа Бога, Благословенная.", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "martyr-epimachus-tone4", 7, 4, "16132befc860c45025f8e5b72d4afbf53fd69d8707110eb70b4877b20f4a8aa7", "f650d71a2842ff5b318720dbbcfc0f3bdb51b83007cb9de5b3b5e8880c47d82f", "58960b3735672c47a0796d9c9cc77d7b441e474298053cc1e90d03d588c4bda9"),
        Record(FeoriaTranslationCatalog.Entry("cross-tone6-friday:6a059bbaf55d27d641da",
            "Пие́ши ча́шу, Христе́, ю́же возжеле́л еси́ стра́стию кре́стною, исто́чники ми́ пролива́яй оставле́ния от живоно́сных ре́бр, ра́ди ребра́ уме́ршему. Пою́ Тя воспева́яй: свяще́нницы благослови́те, лю́дие превозноси́те во вся́ ве́ки.",
            "Ты пьешь, Христе, желанную Тебе чашу крестного страдания, из животворящего бока изливая мне источники прощения, умершему из-за ребра. Я пою Тебе, воспевая: \"Священники, благословляйте, люди, превозносите во все века!\"", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "cross-tone6-friday", 8, 1, "1f0611b4abcc443efd2868bb9e5c640f0d11979667a925896c6753f0df0b9ba4", "6a059bbaf55d27d641da0516002fd011d107f5fe993088153bcbb9f94359304a", "8a02231129c8813ec2c9bd277115bc5aaf106056daefb8606988c4684513a556"),
        Record(FeoriaTranslationCatalog.Entry("cross-tone6-friday:c78a86094bb18a3ab2c1",
            "Егда́ Тя беззако́ннии лю́дие осуди́ша распя́ти, Иису́се, посреде́ беззако́нных, Жизнода́вче Го́споди, потрясе́ся земля́, и вси́ воспева́ху со стра́хом: о́троцы благослови́те, свяще́нницы воспо́йте, лю́дие превозноси́те во вся́ ве́ки.",
            "Когда беззаконные люди осудили Тебя на распятие среди беззаконных, Иисусе, Жизнедатель, Господи, земля потряслась, и все со страхом воспевали: \"Дети, благословляйте, священники, воспевайте, люди, превозносите во все века!\"", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "cross-tone6-friday", 8, 2, "910032b42c7d77f00d3f5f557a60d382f390a73d67e3c3e8bff3ed443bd65aa1", "c78a86094bb18a3ab2c1730c65f8c5280ab4e9d65b92644abfc69494254ec617", "b9583db87ce3b4669fa0680c1dd69c39d04062dd29b4f173dd815ba949ee82bd"),
        Record(FeoriaTranslationCatalog.Entry("cross-tone6-friday:d50b8e326c68afb054c6",
            "Мученичен: Честна́ пред Бо́гом яви́ся ва́ша сме́рть страда́льцы: мно́гим бо причасти́вшеся страсте́м, стра́сти честны́я Христо́вы о́бщницы показа́стеся, вопию́ще единому́дренно: о́троцы благослови́те, свяще́нницы воспо́йте, лю́дие превозноси́те во вся́ ве́ки.",
            "Мученичен: Драгоценной перед Богом явилась ваша смерть, страдальцы: претерпев многие страдания, вы стали причастниками святых страданий Христа, единодушно восклицая: \"Дети, благословляйте, священники, воспевайте, люди, превозносите во все века!\"", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "cross-tone6-friday", 8, 3, "1660a8cd6e463770eebebfdc7a9340c21742616af72f702062c25f22118d0bcf", "d50b8e326c68afb054c654107b103f2571b779d0b843a5b2f4950e7c2ab82aae", "c9a2112d258ad94892ee29a94a94cbca14181e5f3bd0a0f2c5e784d5e674890f"),
        Record(FeoriaTranslationCatalog.Entry("cross-tone6-friday:98c776ba4f8bb530925e",
            "Мученичен: Вои́стинну не плотска́я ва́ша ору́жия, му́ченицы, ко ополче́нию враго́в: наде́жда же, ве́ра и и́стина, и́миже улучи́вше Бо́га, а́нгельским лико́м сочета́стеся вопию́ще Влады́це: свяще́нницы благослови́те, лю́дие превозноси́те во вся́ ве́ки.",
            "Мученичен: Поистине не плотское ваше оружие, мученики, для борьбы с врагами, а надежда, вера и истина. Ими обретя Бога, вы соединились с ангельским сонмом, восклицая Владыке: \"Священники, благословляйте, люди, превозносите во все века!\"", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "cross-tone6-friday", 8, 4, "f6f7001967b1d90ab2e9a9b5799707ef74446fb6aa4d8617518d87d6c97a169d", "98c776ba4f8bb530925e54ca8a5690892225f9df09a2733a98b7e7883290083e", "bfea02ad635d8c42c3a5ef77b12260efa5cc5c263517077eb721284cc11c9db8"),
        Record(FeoriaTranslationCatalog.Entry("cross-tone6-friday:e51c9b73f155cc57094e",
            "Богородичен: Вы́шний Безнача́льне Сы́не, терпи́ши оплева́ния, поноше́ния и Кре́ст, тро́стию руга́тельно бие́мь, Богоро́дица вопия́ше: сла́влю Твое́ долготерпе́ние: Его́же о́троцы благословя́т, свяще́нницы воспева́ют, лю́дие превозно́сят во вся́ ве́ки.",
            "Богородичен: \"Всевышний, Безначальный Сын, Ты терпишь оплевание, поношения и Крест, под насмешки избиваемый тростью, - восклицала Богородица. - Славлю Твое долготерпение\". Его благословляют дети, воспевают священники, превозносят люди во все века.", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "cross-tone6-friday", 8, 5, "6e12192d6d9711510446375e04a03e915022ff357d638a8e2ac4d1949a287795", "e51c9b73f155cc57094e243a9ae9d18e6dd3e486606db461d5dd775dc1c42998", "7ff0fb78792d80a2e9d7fe99e316bc15990490c28ea2388533b786349a5cf65b"),
        Record(FeoriaTranslationCatalog.Entry("apostles-stachys-amplias-urban-narcissus-apelles-aristobulus-tone1:798d606fff562653b256",
            "В мире, я́коже молния, яви́стеся, Боговидцы, попаля́юще у́бо лесть,/ пою́щия же, сы́ны дне показу́юще, и вопию́щия:/ благословите вся дела Господня Го́спода,/ пойте и превозносите во вся ве́ки.",
            "Вы явились в мире, как молния, боговидцы, сжигая заблуждение, а воспевающих и восклицающих делая сынами дня: \"Все дела Господни, благословляйте Господа, воспевайте и превозносите во все века!\"", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "apostles-stachys-amplias-urban-narcissus-apelles-aristobulus-tone1", 8, 1, "c76732754cfc25ccba841c1e90913940a5ca7f9968b447a6374a6d9ec709786f", "798d606fff562653b25698385e2a00728bdaeafb3878e57cf8fb96592fb22c88", "3f2461ba885c05bac0d46de0be9cce4d1035829837110dfeef0c1068aeb819d8"),
        Record(FeoriaTranslationCatalog.Entry("apostles-stachys-amplias-urban-narcissus-apelles-aristobulus-tone1:e68d0fc4fefb091ed63e",
            "Сладкою со́лию твои́х, Ампли́е, учений ле́сти гни́лость очи́стил еси́./ Темже, чтуще тя, поем:/ благословите вся дела Господня Го́спода,/ пойте и превозносите во вся ве́ки.",
            "Сладкой солью твоих учений, Амплий, ты очистил гниль заблуждения. Поэтому, почитая тебя, поем: \"Все дела Господни, благословляйте Господа, воспевайте и превозносите во все века!\"", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "apostles-stachys-amplias-urban-narcissus-apelles-aristobulus-tone1", 8, 2, "acc87ca80649cd5104462d23ea3d9c71d683df8c0ac82eb4d305979a1e1bbd27", "e68d0fc4fefb091ed63eb1f7fc529f69f1d4bd1664c98a4a3efb7b3afbd439c4", "266e4b38b27eaddeff6ebb6ffa15806a08bc713905a1c30db7d855b2903debef"),
        Record(FeoriaTranslationCatalog.Entry("apostles-stachys-amplias-urban-narcissus-apelles-aristobulus-tone1:92e41938fd23b1a85138",
            "Да поется Стахи́й славный и Ампли́й, Апе́ллий же и Нарки́сс,/ Урван же и всемудрый, вопия́й верно, Аристову́л:/ благословите вся дела Господня Го́спода,/ пойте и превозносите во вся ве́ки.",
            "Да будут воспеты славный Стахий и Амплий, Апеллий и Наркисс, Урван и премудрый Аристовул, с верой восклицающий: \"Все дела Господни, благословляйте Господа, воспевайте и превозносите во все века!\"", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "apostles-stachys-amplias-urban-narcissus-apelles-aristobulus-tone1", 8, 3, "b767e2d14bb1597f5c6f8b902a48e49a1862037c921726a2c873abdc51fbc61e", "92e41938fd23b1a85138d1778fe24e01f6cc19832703694ea824608ca3c0a4e7", "31b36d76a2538305888dfb76f65e9e21fe44653781a68c97ec77f36c64a00b06"),
        Record(FeoriaTranslationCatalog.Entry("apostles-stachys-amplias-urban-narcissus-apelles-aristobulus-tone1:1d02b537acd51986b33f",
            "Богородичен: Тя и сте́ну, и прибежище, и ле́ствицу,/ к высоте преводя́щу человечество, Всенепоро́чная Чи́стая, ве́дяще, зовем:/ благословите вся дела Господня Го́спода,/ пойте и превозносите во вся ве́ки.",
            "Богородичен: Зная Тебя как стену, прибежище и лестницу, возводящую человечество к высоте, совершенно Непорочная, Чистая, взываем: \"Все дела Господни, благословляйте Господа, воспевайте и превозносите во все века!\"", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "apostles-stachys-amplias-urban-narcissus-apelles-aristobulus-tone1", 8, 4, "8ce05f2de42560b7a4dcb158bc3cde78435195d2f4b97818a2d35b9244bb9844", "1d02b537acd51986b33f25699710780dd40b1be9eb3627e902fff861101de943", "bd7b4c7724609223065b223361afb7cf3edac2bae871cca2faf07e04900b2ec0"),
        Record(FeoriaTranslationCatalog.Entry("martyr-epimachus-tone4:22792189e6a372ae0bec",
            "Победителя ле́сти показавшаго и беззаконных муже́й, венцено́сца Епимаха,/ пойте, отроцы, священницы, благословите,/ лю́дие, превозносите во вся ве́ки.",
            "Явившего венценосца Епимаха победителем заблуждения и беззаконных мужей воспевайте, дети; священники, благословляйте; люди, превозносите во все века!", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "martyr-epimachus-tone4", 8, 1, "35f7aa08943f0426e8f34a50dd5a0c9a886817970cb38f238f585aaf16cdae8f", "22792189e6a372ae0beca0a9e154d06dd43c1370421a91dfc9689eee11f2f4db", "8342ad9b297add34753a5afba2cbf1880864516aadd84a8a7781443b871bef43"),
        Record(FeoriaTranslationCatalog.Entry("martyr-epimachus-tone4:fca9fa08547b63b17076",
            "Врача́ страсте́й и неду́гов, нам Даровавшаго, лю́тых, страстоно́сца Епимаха,/ пойте, отроцы, священницы, благословите,/ лю́дие, превозносите Его́ во ве́ки.",
            "Даровавшего нам врача тяжких страстей и недугов, страстотерпца Епимаха, воспевайте, дети; священники, благословляйте; люди, превозносите Его вовеки!", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "martyr-epimachus-tone4", 8, 2, "5df4383a705928abce46d937473d7d0161f26ba258443bec2963fb73197901c9", "fca9fa08547b63b17076e0b959738b41ec5d867781e0810986aee38c544746ac", "90d4e1d8bc5adc6a44d4fbe2c56d4b8a8139a58cce16c731fd6c839984a1586f"),
        Record(FeoriaTranslationCatalog.Entry("martyr-epimachus-tone4:d89cb2491f71851abd18",
            "На земли́ па́мять Епимаха, возвеличившаго Христа/ и Тем исцели́вшаго различныя неду́ги,/ свяще́ннии, пойте и превозносите Его́ во ве́ки.",
            "Христа, возвеличившего на земле память Епимаха и через него исцелившего разные недуги, священники, воспевайте и превозносите вовеки!", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "martyr-epimachus-tone4", 8, 3, "960f327f216b6ddc3a01b85ce0e4e557916b5a8e817b69239899c761874fd6f5", "d89cb2491f71851abd18022bed416c2b98b54dacb709888035c28f1badc167df", "437c9f696f4df7c6c47f85382fdfa64a9fda3d6e3274e2c25412d1a80434e467"),
        Record(FeoriaTranslationCatalog.Entry("martyr-epimachus-tone4:2c29ec6fc6ac756e0b83",
            "Богородичен: Неизреченно и безсеменно заченшую и рождшую Де́ву Христа́ Бо́га на́шего,/ пойте, дети, священницы, благословите,/ лю́дие, превозносите Ю во веки.",
            "Богородичен: Деву, неизреченно и без семени зачавшую и родившую Христа, Бога нашего, воспевайте, дети; священники, благословляйте; люди, превозносите Ее вовеки!", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "martyr-epimachus-tone4", 8, 4, "fb170a9d8d5a64b343abf92fb39189972b0548af2ed33db854d0b86782706814", "2c29ec6fc6ac756e0b83d50dbb3473727b7c8ac8a0a206da00e6c25552e08a50", "b26b151d1f7721dab0fab6ac4fc9732078199fd7fd67432a93ba5fe265ae6bc4"),
        Record(FeoriaTranslationCatalog.Entry("katavasia-tone4-four-odes:9151b58287d2cf6b6cf5",
            "Ирмос, глас 4: Во о́бразе А́нгела,/ я́вльшагося в пещи́ огненней песнословцем/ Христа́ Бо́га, пойте, отроцы,/ священницы, благословите,/ лю́дие, превозносите во вся ве́ки.",
            "Ирмос, глас 4: Христа Бога, явившегося в образе Ангела воспевающим Его в огненной печи, воспевайте, дети; священники, благословляйте; люди, превозносите во все века!", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "katavasia-tone4-four-odes", 8, 1, "2dde3ecd9befa75e705994d0f5a9762c079bf1ca901046ed2a37ecd275c0d02c", "9151b58287d2cf6b6cf5e82928c158bd27e524abe062e012265019be41c505f2", "5038e6c39c40e9b4ab19f176a55432f0d2d2bbf03d02cddbaed2a08d767493b0"),
        Record(FeoriaTranslationCatalog.Entry("cross-tone6-friday:b4c6b399603d3b4ebf47",
            "Да сне́дию истле́вшаго сла́достною Дре́ва, еди́не Спа́се, я́ко бла́г изба́виши от тли́, распя́тися пло́тию, и умертви́тися изво́лил еси́: пое́м непреста́нно, Иису́се, мно́гое благоутро́бие и си́лу Твою́.",
            "Чтобы избавить от тления того, кто истлел от сладкого вкушения с древа, Ты, Единый Спаситель, как Благой, изволил быть распятым плотью и умерщвленным. Непрестанно воспеваем, Иисусе, Твое великое милосердие и силу.", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "cross-tone6-friday", 9, 1, "7219d8430b234d92a1fd56e8745e5b59e4f69a351d08953074f60561f3bb7c82", "b4c6b399603d3b4ebf47c68e20f64f37b6dcd0eb29fed039433a8466bd1fb27a", "f871af6bde9c6181433323f2a06892c75c20cdaac4c185a7bac15da10c74d46c"),
        Record(FeoriaTranslationCatalog.Entry("cross-tone6-friday:909e7ab5d84b5eb7c058",
            "О ка́ко претерпе́л еси́ боле́зни, на Кресте́ простира́емь, от боле́зней лю́тых изъима́я мя́, Спа́се? Ка́ко те́рниями венча́выйся, все́ попали́л еси́ страсте́й те́рние? Ка́ко о́цта напои́выйся, весе́лия ча́шу на́м раствори́л еси́?",
            "О, как Ты претерпел боль, будучи распростерт на Кресте, избавляя меня от тяжких страданий, Спаситель? Как Ты, увенчанный терниями, сжег все терние страстей? Как Ты, напоенный уксусом, приготовил нам чашу веселья?", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "cross-tone6-friday", 9, 2, "4e9f4905f7548055b1e37c27ee1cf5fc7a7742b1180041fe4daf8878ca077621", "909e7ab5d84b5eb7c0580b6482cc6f3f535ef5c5544df5bf3a2b33dba5b585d4", "280f3efbce176b00678328138400b83bd2d83009906deb0a5d7b45644e904ce4"),
        Record(FeoriaTranslationCatalog.Entry("cross-tone6-friday:6a7bdc61985757f8fce7",
            "Мученичен: Стесня́еми вси́, и в темни́цы вмета́еми, и на у́ды страда́льцы разсеца́еми лю́те, и по колесе́х же́стоко протяза́еми, и во снеде́ние звере́м вдава́еми, Христа́ все́х Влады́ки не отверго́стеся.",
            "Мученичен: Угнетаемые, ввергаемые в темницы, страдальцы, вы все, жестоко рассекаемые на части, растягиваемые на колесах пыток и отдаваемые на съедение зверям, не отреклись от Христа, Владыки всех.", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "cross-tone6-friday", 9, 3, "26bfb3f823f540f1b88e1ee284746991292dd7486c87bf0d427d30fa475deaad", "6a7bdc61985757f8fce7fb7c21d6b3379cf784be688f526694f24ff89af7d474", "ef1f9b994d48d2693f58c4d39258a90de815bbd1df1751a94a8e8b82fe1964c8"),
        Record(FeoriaTranslationCatalog.Entry("cross-tone6-friday:61cb660068438530a146",
            "Мученичен: Со́лнечных сия́ний мно́жайши сия́ет страда́лец всесве́тлая и благознамени́тая па́мять: и ду́шы благочести́вых просвеща́ет всегда́, и отгоня́ет тьму́ страсте́й, и искуше́ний, и де́монский расточа́ет мра́к глубоча́йший.",
            "Мученичен: Светлее солнечных лучей сияет всесветлая и славная память страдальцев, всегда просвещает души благочестивых, отгоняет тьму страстей и искушений и рассеивает глубочайший мрак демонов.", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "cross-tone6-friday", 9, 4, "2570e97ffeb5a2219e3e0ddcc1fe93254d403cca9e6c84d453d19108f9e8b115", "61cb660068438530a14618576edf280cd4c13af315b453ea506db42299b48b9e", "ce4d5ee717ccbc0438e69e0c5121ba8372c2a5d2830ad20e9eca9f30548edcd9"),
        Record(FeoriaTranslationCatalog.Entry("cross-tone6-friday:6827c91c59d0949cd76c",
            "Богородичен: Но́сиши Нося́щаго вся́, и держи́ши я́ко Младе́нца на руку́, изба́вльшаго на́с от руки́ бори́теля врага́, Пречи́стая Влады́чице, и зри́ши возвы́шена на Дре́ве Кре́стнем из я́мы зло́бы на́с изба́вльшаго.",
            "Богородичен: Ты носишь Носящего все и держишь как Младенца на руках Избавившего нас от руки враждебного борца, Пречистая Владычица, и видишь вознесенным на Крестном Древе Избавившего нас от ямы зла.", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "cross-tone6-friday", 9, 5, "5da1c734383f842416a870797bb72bc605009fcbff5437f8ee584067cd03b3ad", "6827c91c59d0949cd76c383f65438fc76682f31c4c98cb65799bcc5eb654d1f6", "708f8d1b804977f3eab1a2285c2b1e9dc63fa52ada2ff509e8e99a5252f0d22e"),
        Record(FeoriaTranslationCatalog.Entry("apostles-stachys-amplias-urban-narcissus-apelles-aristobulus-tone1:cf4f67ffa403a25809c9",
            "Да земныя концы́, исполненныя пре́лести борца́ и наполненныя омраче́ния безбожия,/ бла́гости светом озари́ши зна́ния/ Твоя́ спаси́тельныя зари́, Щедре,/ сим послал еси́.",
            "Чтобы озарить края земли, полные обмана врага и мрака безбожия, благим светом познания, Ты, Милосердный, послал к ним Свои спасительные лучи.", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "apostles-stachys-amplias-urban-narcissus-apelles-aristobulus-tone1", 9, 1, "14402116985c33fc67d4816e2483269298fe6fd01833dc84d038f60386375ca9", "cf4f67ffa403a25809c9f2adc7fa6bf716503f326b7c146cb93befed2f72790d", "cc94125b383b551dce787f75bdb5d22c37d9613aa3b08c32bcb2d3b5fabaac4f"),
        Record(FeoriaTranslationCatalog.Entry("apostles-stachys-amplias-urban-narcissus-apelles-aristobulus-tone1:1d126dd14b4f78fbcb22",
            "Яви́лся еси́ тезоиме́нно, славне, спаси́тельный клас, пшеницу требующим нося́щь,/ утверждение Богоразумия подаю́щую и гла́да у́мнаго изима́ющую,/ верою тя и любовию, священнопроповедниче, поющим.",
            "Ты явился сообразно своему имени, славный, спасительным колосом, приносящим нуждающимся пшеницу, которая утверждает в богопознании и избавляет от духовного голода нас, с верой и любовью воспевающих тебя, священный проповедник.", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "apostles-stachys-amplias-urban-narcissus-apelles-aristobulus-tone1", 9, 2, "6316a7716119b32354099b168b936aa2455b412533089bf9013d1255212b8f6a", "1d126dd14b4f78fbcb22cd0d5a884e9e7745ec88aeeef8404d2c903e667357a1", "573a0536a2da1ac6464600ce96f1c2d40dcb63c40312791c1a2f960395bfa666"),
        Record(FeoriaTranslationCatalog.Entry("apostles-stachys-amplias-urban-narcissus-apelles-aristobulus-tone1:34073e4e9006b62c6c17",
            "Уста́ Бо́жия быв, ри́торов язы́ки неглаго́ливы показа́л еси́/ и из горта́ни вра́жия, Аристову́ле, извлекл еси́ ду́ши,/ и привел еси́ Господу спасе́ны, соверше́нны познанием.",
            "Став устами Бога, ты заставил умолкнуть языки ораторов и из пасти врага, Аристовул, извлек души и привел их ко Господу спасенными и совершенными в познании.", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "apostles-stachys-amplias-urban-narcissus-apelles-aristobulus-tone1", 9, 3, "a577cdffbfa4e48fad88933be63d9ed6b13fb92d64481ffa8077620286ff3db1", "34073e4e9006b62c6c176aa9f1e87a6938d10c6f1e1220268d60544b40d75552", "ccaccc9e1e5d1e222e71d20593f6d2699281ca6cd349751b167b2d940a3faca0"),
        Record(FeoriaTranslationCatalog.Entry("apostles-stachys-amplias-urban-narcissus-apelles-aristobulus-tone1:b118627e6b87f18cefbd",
            "Небеса́ у́бо бы́ша Боговидна живуща, Божии апостоли,/ и́же на земли́ чисто вас чтущия и искренно выну блажа́щия,/ причастники вечныя сподо́бите све́тлости.",
            "Вы стали живыми богоподобными небесами, апостолы Божии; тех, кто на земле чисто чтит вас и всегда искренне прославляет, удостойте стать причастниками вечного света.", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "apostles-stachys-amplias-urban-narcissus-apelles-aristobulus-tone1", 9, 4, "e30e2a0d181eec4072846a8a8cd2f249bc1ac71bf0df6dfaf633ca6968d74245", "b118627e6b87f18cefbdfb485bbba8519294f42b3b785a1b3e3acf3b4aca42ac", "273a972f12eed0ee52c16f58ca4d6abbca5ffc9b649545838361e44429ba1dd3"),
        Record(FeoriaTranslationCatalog.Entry("martyr-epimachus-tone4:4731c210d32235922085",
            "Ты я́ко возлюбил еси́ совершенно и умре́ти за уме́ршаго нас ради Христа./ Темже от Него в Вышних вво́инился еси́, мучениче,/ Егóже со Отцем и Духом песньми величаем.",
            "Ты всецело возлюбил даже умереть за Христа, умершего ради нас; поэтому Он причислил тебя, мученик, к небесному воинству. Его с Отцом и Духом мы прославляем песнями.", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "martyr-epimachus-tone4", 9, 1, "e5a278e1a7228712e99016228397b2a07629bb376613a8c78dcc571c40e3e5ce", "4731c210d322359220858fb426f7b4f4553a73cbb67fb2fbac3ce0970b778573", "700d1db2ded55e358f6ece740a8196859852a3ba8afef2e6cc56f92a2fd2d70d"),
        Record(FeoriaTranslationCatalog.Entry("martyr-epimachus-tone4:0751818db60337634573",
            "Ты я́ко на земли́ Спа́са Бо́га испове́дал еси́ пред нечестивыми мучители верно;/ ны́не в вышних от Него пред А́нгелы, свидетелю Епима́ше,/ и от Отца и Ду́ха славою венчался еси́.",
            "Ты с верой исповедал на земле Спасителя Бога перед нечестивыми мучителями; ныне в вышних Он перед Ангелами, свидетель Епимах, а также Отец и Дух увенчали тебя славой.", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "martyr-epimachus-tone4", 9, 2, "1ff8f77fe6a4501ead29a830b65c366c29504b2baa0328833a5b8e25557a3e18", "0751818db603376345731be0e1f3fcabb6443818b5a303ed78026f3d5c8d90a3", "c7b2d21e684bd0c31b36a6a84e44d8588f563dc0b1d4de028ffd5e79d5c465e3"),
        Record(FeoriaTranslationCatalog.Entry("martyr-epimachus-tone4:543ea272507e9dc893cb",
            "Богородичен: Тя, светоносный облак, и Чистую и славную Де́ву и Матерь Божию,/ Моисею я́вльшуюся та́инственно на горе́ Сина́йстей неопали́мую купину́,/ в пе́ниих величаем.",
            "Богородичен: Тебя, светоносное облако, Чистую и славную Деву и Матерь Божию, таинственно явившуюся Моисею на горе Синайской несгорающей купиной, мы прославляем песнями.", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "martyr-epimachus-tone4", 9, 3, "8f7bf40893d806d4abe9bc71080cc2a185d7e1731f17645c7f727103a203e64f", "543ea272507e9dc893cb35a4ad66d232458a12fd20d79506e62ccb9b9ccfd7d8", "bfb0e1945b698b8705d667607b9b98e352d083a59e3a6cb3e4bbea1f7e887f6f"),
        Record(FeoriaTranslationCatalog.Entry("katavasia-tone4-four-odes:63570a3d90caced5c89d",
            "Ирмос, глас 4: Тя, невместимое Слово во утро́бу вместившую,/ Небе́с простра́ннейшую и Херувимов сла́внейшую,/ Богоро́дице Чи́стая, песньми величаем.",
            "Ирмос, глас 4: Тебя, вместившую в чреве невместимое Слово, более просторную, чем небеса, и более славную, чем Херувимы, Чистая Богородица, прославляем песнями.", revision = 3, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "katavasia-tone4-four-odes", 9, 1, "b64b007a4b95dd522d59a782a4a4fe1bd3684869f71d4912017445e6425e5b8e", "63570a3d90caced5c89dd841104ccc63402060b9cf5763f26b203fbece3b99c2", "be8d8be3a053ec04df4c98f98d9bef72c86fceb52f5a5232ea68957b67e0b0ea")
    )
    val entries: List<FeoriaTranslationCatalog.Entry> = records.map { it.entry }

    init {
        require(records.size == 105 && records.map { it.entry.id }.distinct().size == 105)
        require(records.map { it.normalizedOriginalSha256 }.distinct().size == 105)
        require(records.all { record ->
            BookText.sha256(record.entry.original) == record.originalSha256 &&
                BookText.sha256(BookText.normalized(record.entry.original)) == record.normalizedOriginalSha256 &&
                BookText.sha256(record.entry.russian) == record.russianSha256
        })
    }

    private val byNormalizedOriginal = records.associateBy { it.normalizedOriginalSha256 }

    /** Includes every lexical word and metadata label; no extra speaker/prefix removal here. */
    fun recognizes(original: String, translation: BookTranslation): Boolean {
        if (translation.source != BookTranslationIndex.FEORIA_TRANSLATION_SOURCE || translation.meaning != null) return false
        val record = byNormalizedOriginal[BookText.sha256(BookText.normalized(original))] ?: return false
        return BookText.sha256(translation.russian) == record.russianSha256 && translation.russian == record.entry.russian
    }
}
